	var parts []string
	if s.Base != "" && s.Branch != "" && s.Base != s.Branch && (s.AheadCommits > 0 || s.FilesChanged > 0) {
		parts = append(parts,
			fmt.Sprintf("%d commits", s.AheadCommits),
			fmt.Sprintf("%d files changed", s.FilesChanged),
		)
